ch3.starterCode:
# Weather imeshapangwa tayari
# hewa ni "mvua" au "jua"

# Chagua njia sahihi!
kama (hewa ni "mvua") {
  acha njia = "pango"
} la sivyo {
  acha njia = "mto"
}

andika(njia)

ch4.starterCode:
# Vuka daraja kwa steps 5

acha hatua = 0

rudia (acha i = 0; i chini 5; i++) {
  hatua = hatua + 1
}

andika(hatua)

ch5.starterCode:
# Create function ya mara mbili

kazi maraMbili(nambari) {
  rudisha nambari * 2
}

acha jibu = maraMbili(7)
andika(jibu)
